    "oneLine": "Ressam Heo Baek-ryeon'un adını verdiği, Mudeung Dağı'nın yabani çalılarından tavada kavrulmuş bir çay — erken baharın narin yaprakları taze yeşil bir koku ve nazik bir tatlılıkla açılır.",
