    "oneLine": "Kraliçe Victoria'nın Oriental Beauty adını verdiği söylenen beyaz uçlu oolong — yaprak bitlerinin ısırdığı yapraklar bal, olgun şeftali ve gül verir, yuvarlak bir tatlılıkla.",
