    "process": "Soldurma → kavurma → top şekline yuvarlama → kurutma. Oksidasyon yüzde 15–20'de durur.",
    "story": "1980'lerde Taipei Muzha'da tesadüfen bulunan ve dört mevsim boyunca sürgün vermeye devam eden bir ağacın çaya adını verdiği söylenir. Kokusu, onu yasemin çayı için yaygın bir baz yapar.",
