    "process": "Soldurma → kavurma → şerit hâlinde yuvarlama → kurutma. Yüzde 8–12 oksidasyonla yeşil çaya yakın durur.",
    "story": "Adının, kokusunu korumak için çayın kâğıda sarılmasından geldiği söylenir. Kokulandırılmış pouchong'dan farklı olarak köken pouchong, yaprağın kendi çiçeklerine göre değerlendirilir.",
    "flavor": "Orkide ve gardenya, yeşil bir bitiş, hafif ve berrak.",
